function parseZip(bytes) {
  const buf = Buffer.from(bytes), entries = {}; let at = 0;
  while (buf.readUInt32LE(at) === 0x04034b50) {
    assert.equal(buf.readUInt16LE(at + 8), 0, "valid stored ZIP entry");
    const size = buf.readUInt32LE(at + 18), nameSize = buf.readUInt16LE(at + 26), extraSize = buf.readUInt16LE(at + 28);
    const name = buf.subarray(at + 30, at + 30 + nameSize).toString("utf8"), start = at + 30 + nameSize + extraSize, body = buf.subarray(start, start + size);
    let crc = 0xffffffff; for (const byte of body) { crc ^= byte; for (let i = 0; i < 8; i++) crc = crc & 1 ? 0xedb88320 ^ crc >>> 1 : crc >>> 1; }
    assert.equal((crc ^ 0xffffffff) >>> 0, buf.readUInt32LE(at + 14), "CRC of " + name);
    entries[name] = body.toString("utf8"); at = start + size;
  }
  assert.equal(buf.readUInt32LE(at), 0x02014b50, "central directory follows data");
  const eocd = buf.length - 22; assert.equal(buf.readUInt32LE(eocd), 0x06054b50); assert.equal(buf.readUInt32LE(eocd + 16), at); assert.equal(buf.readUInt16LE(eocd + 10), Object.keys(entries).length);
  for (const xml of Object.values(entries)) assert.equal(new w.DOMParser().parseFromString(xml, "application/xml").querySelector("parsererror"), null, "well-formed OOXML");
  return entries;
}
function xml(text) { return new w.DOMParser().parseFromString(text, "application/xml"); }
function cell(doc, ref) { const c = doc.querySelector('c[r="' + ref + '"]'); return c ? { type: c.getAttribute("t"), text: c.textContent } : null; }
// The summary can grow for multiple bonus months / Sunday dates. Assert the
// actual filter-defined table, not a fixed row 7 from the old register layout.
function registerLayout(doc) {
  const match = /^A(\d+):I(\d+)$/.exec(doc.querySelector('autoFilter').getAttribute('ref'));
  assert.ok(match, 'complete filter-defined register');
  const header = Number(match[1]), last = Number(match[2]);
  return { header, first: header + 1, last, total: last + 1, count: last - header };
}
function rcell(doc, col, index = 0) { return cell(doc, col + (registerLayout(doc).first + index)); }
function registerMetric(doc, label) {
  const value = Array.from(doc.querySelectorAll('c')).find((c) => c.textContent === label);
  assert.ok(value, 'top summary label: ' + label);
  assert.ok(Number(value.getAttribute('r').replace(/\D/g, '')) < registerLayout(doc).header, label + ' must be above register');
  const target = value.nextElementSibling?.nextElementSibling; assert.ok(target, label + ' numeric value');
  return { type: target.getAttribute('t'), text: target.textContent, cell: target };
}

async function importFixture(payload) {
  let fileInput; const original = w.HTMLInputElement.prototype.click;
  w.HTMLInputElement.prototype.click = function () { if (this.type === "file") fileInput = this; else original.call(this); };
  try { action("importData"); } finally { w.HTMLInputElement.prototype.click = original; }
  assert.ok(fileInput); Object.defineProperty(fileInput, "files", { value: [new w.File([JSON.stringify(payload)], "backup.json", { type: "application/json" })] });
  // Wait for the real FileReader completion, not a 35ms sleep that can finish
  // before I/O under concurrent Chromium QA and leak an import into later tests.
  const read = w.FileReader.prototype.readAsText; let timer;
  try {
    await new Promise((resolve, reject) => {
      timer = setTimeout(() => reject(new Error('Backup FileReader did not complete')), 3000);
      w.FileReader.prototype.readAsText = function (...args) {
        this.addEventListener('loadend', resolve, { once: true }); return read.apply(this, args);
      };
      fileInput.dispatchEvent(new w.Event("change"));
    });
  } finally { clearTimeout(timer); w.FileReader.prototype.readAsText = read; }
}
function assertPdf(pdf) {
  assert.ok(pdf.startsWith("%PDF-1.4")); assert.ok(pdf.endsWith("%%EOF"));
  const at = Number(pdf.match(/startxref\s+(\d+)\s+%%EOF$/)[1]); assert.equal(pdf.slice(at, at + 4), "xref");
  const lines = pdf.slice(at).split("\n"), count = Number(lines[1].split(" ")[1]);
  for (let id = 1; id < count; id++) { const offset = Number(lines[id + 2].slice(0, 10)); assert.ok(pdf.slice(offset).startsWith(id + " 0 obj\n"), "xref object " + id); }
  const positions = [...pdf.matchAll(/ rg 1 0 0 1 ([-\d.]+) ([-\d.]+) Tm /g)].map((match) => [Number(match[1]), Number(match[2])]);
  assert.ok(positions.length); assert.ok(positions.every(([x, y]) => x >= 39.9 && x <= 555.4 && y >= 30 && y <= 800.1), "text stays within paper and above footer");
}
